"""Local request evidence. No service vocabulary, transport, or delivery."""
import re
from message_classification import positive
REQUEST=r'\b(?:нуж(?:ен|на|но|ны)|ищ(?:у|ем|ется|ут)|требу(?:ется|ются)|закажу|заказать|набираем|передадим|передаем|передавать|посоветуйте|порекомендуйте|есть\s+заказчик|вакансия\s*:\s*(?:собрать|сверстать|создать)|кто\s+(?:сможет|может|сделает|возьмется|переделает)|помогите\s+(?:сделать|доработать|сверстать))\b|\bв\s+поиске\b'
PATTERNS={
 'request':REQUEST,
 'offer':r'ищу\s+(?:работу|ваканс\w*|заказы)|рассмотрю\s+ваканс|предлага\w*\s+(?:свои\s+)?услуги|наши\s+услуги|оказыва\w*\s+услуги|с\s+чем\s+можем\s+помочь|что\s+мы\s+предлагаем|реклама\s+вашего\s+оффера|продвигаем\s+любые\s+офферы|#помогу\b|мое\s+портфолио|беру\s+проекты|открыта\s+запись|готов\s+помочь|обращайтесь|рекомендую\s+вам\s+бота|есть\s+бесплатный\s+тариф|бесплатно\s+и\s+без\s+регистрации|запишитесь.{0,100}вебинар|на\s+бесплатном\s+вебинаре|ищу.{0,70}фидбек',
 'sales':r'менеджер\w*\s+по\s+продаж\w*|партнер\w*\s+по\s+продаж\w*|приводи\w*\s+клиент\w*|привед\w*\s+(?:нам\s+)?клиент\w*|привлечени\w*\s+(?:новых\s+)?клиент\w*|поиск\w*\s+клиент\w*|ищ\w*\s+клиент\w*|продавать\s+мои|продавать\s+(?:наши\s+)?сайты|приведенн\w*\s+клиент\w*|разработк\w*\s+и\s+запуск\s+беру\s+на\s+себя',
 'staff':r'\b(?:в\s+штат\w*|штатн\w*\s+ваканси\w*|полный\s+день|оклад\w*|трудоустройств\w*|полная\s+занятость|зарплат\w*|оформлен\w*\s+по\s+тк)',
 'closed':r'исполнитель\s+найден|нашли\s+исполнителя|задача\s+закрыта|вакансия\s+закрыта|отклики\s+закрыты|неактуально|не\s+актуально',
 'pool':r'субподряд|в\s+подрядку|на\s+(?:постоянн\w*\s+)?подряд|постоянн\w*\s+сотруднич|долгосрочн\w*\s+сотруднич|пул\s+(?:дизайнер|исполнител)|поток\s+задач|переда(?:вать|ем|дим|ют|дут)\b.{0,35}(?:заказ\w*|проект\w*|сайт\w*|лендинг\w*|разработчик\w*|исполнител\w*)|для\s+передачи\s+проект\w*'}
def quote(text,start,end,field,rule):
    return {'field':field,'rule':rule,'quote':text[start:end],'start':start,'end':end}
def facts(text):
    s=text.lower().replace('ё','е').replace('\n',' ').replace('\r',' ')
    return s,{k:positive(p,s) for k,p in PATTERNS.items()},[(m.start(),m.end()) for m in re.finditer(r'.+?(?:[.!?;](?=\s|$)|$)',text,re.S)]

# Conjugations and bounded command forms, not arbitrary fuzzy spell correction.
REQUEST=REQUEST.replace('ищ(?:у|ем|ется|ут)','ищ(?:у|ем|ет|ется|ут)')
PATTERNS['request']=REQUEST
